order=[0,1,2,3,4,5]
bases=[2,9,8,7,4,6]
sel=[motifs[i] for i in order]
tiles=[]
for b,m in zip(bases,sel):
 t=[[b]*7 for _ in range(7)]
 for i in range(5):
  for j in range(5): t[i+1][j+1]=b if m[i][j]==5 else m[i][j]
 tiles.append(t)
out5=[]
for a,c in [(0,1),(2,3),(4,5)]:
 for r in range(7): out5.append(tiles[a][r]+tiles[c][r])
print('\n'.join(' '.join(map(str,r)) for r in out5))

